  `file_type` varchar(60) NOT NULL DEFAULT 'none',
  `is_ready_for_recalculation` tinyint(1) NOT NULL DEFAULT '1',
  `is_kpi_indicator` tinyint(1) DEFAULT '0',
  `is_equivalence_formula` tinyint(1) DEFAULT '0',
  `prioritize_calculate_from_computed` tinyint(1) DEFAULT NULL,
  `calculation_priority` tinyint(1) NOT NULL DEFAULT '1',
  `nos_of_indicators_for_equivalence_formula` varchar(250) DEFAULT NULL,
  `keep_raw_number_if_not_computable` tinyint(1) DEFAULT '0',
  `use_ingredient_logic_for_eu_aggregation` tinyint(1) DEFAULT '0',
  `remove_ratios_bigger_than_1_for_eu_aggregation` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idindicators_computation_algorithm_id_UNIQUE` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=278 DEFAULT CHARSET=utf8;
